package com.gardensmc.gardensplayers.util;

/**
 * Names of the server's worlds, as the server (and Multiverse) knows them.
 */
public final class Worlds {

    public static final String GARDENS = "gardens";
    public static final String GARDENS_NETHER = "gardens_nether";
    public static final String GARDENS_END = "gardens_the_end";

    // regenerated by /genresource + /resetresource
    public static final String RESOURCE = "resource_world";
    public static final String RESOURCE_NETHER = "resource_nether";
    public static final String RESOURCE_END = "resource_the_end";

    private Worlds() {
    }

    /** What players call a world: "Gardens", "Nether", "Resource World", ...; any other by its own name. */
    public static String displayName(String world) {
        return switch (world) {
            case GARDENS -> "Gardens";
            case GARDENS_NETHER -> "Nether";
            case GARDENS_END -> "The End";
            case RESOURCE -> "Resource World";
            case RESOURCE_NETHER -> "Resource Nether";
            case RESOURCE_END -> "Resource End";
            default -> world;
        };
    }
}
